import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const u=JSON.parse('{"title":"第05章 你来","description":"","frontmatter":{},"headers":[],"relativePath":"第05章_你来.md","filePath":"第05章_你来.md"}'),o={name:"第05章_你来.md"};function r(n,p,s,c,i,d){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第05章-你来" tabindex="-1">第05章 你来 <a class="header-anchor" href="#第05章-你来" aria-label="Permalink to &quot;第05章 你来&quot;">​</a></h1><p>那件事是在正月里来的。</p><p>那天下午我在院子里晒被子。太阳难得出来了，奶奶说要把床上的东西都翻出来过一遍。我抱着被子下楼，挂在绳子上，用竹竿拍，一拍就是一层灰，在光里飘。</p><p>奶奶也下来了，搬了张小椅子坐在楼下，看着被子，怕风把它吹到地上。她问我学校里的事，我说还行。她哦了一声，伸手帮我按住被角。她没有问我手上那个手机，一次也没有。我们家没有人问别人在跟谁讲话，这不是体谅，是我们这里的人从小就没被问过，长大了也就不问别人。</p><p>过了一会儿她说，晒被子要挑太阳大的日子，阴天晒了不如不晒。</p><p>手机在楼上的桌上震了一下。我没听见。等我把被子都挂完上去，看到三条消息。</p><p>「在吗」</p><p>「有件事」</p><p>「算了」</p><p>隔了十分钟，又来一条。</p><p>「你在不在」</p><p>我回，在，刚下楼了。</p><p>她很快回来：你这个人。</p><p>我问，什么事。</p><p>她说，有个人来找我。</p><p>我问，谁。</p><p>她说，以前的。</p><p>我拿着手机站在阳台上，看了一眼楼下那排被子。风不小，被子鼓起来，又慢慢塌下去。</p><p>我问，来找你干嘛。</p><p>她说，说想跟我复合。</p><p>我说，你们以前在一起过？</p><p>她说，不算，就是那时候他一直追我。</p><p>我说，那你当时怎么说的。</p><p>她说，我拒绝了啊。</p><p>我说，那就完了。</p><p>她说，他现在又来了。</p><p>我说，那你还拒绝。</p><p>她说，你以为我没说吗。</p><p>她把话截在这儿。我等了一会儿，她没再发。我问，那你到底想怎么办。</p><p>她说，我不知道。</p><p>她说，你替我想。</p><p>我那时候真的在想。我坐在阳台的小凳子上，把能想到的办法在心里过了一遍。我说，要不你把话说明白一点，别留余地。她说，说过了，没用。我说，那就不回他。她说，他天天发，我拉黑了他还能找别人带话。我说，那你就再明确一次。她说，我不想说得太难听。</p><p>我说，那怎么办。</p><p>她说，我问你呢。</p><p>我说，我想不出来。</p><p>她说，你这个人真没用。</p><p>我说，对不起。</p><p>她说，谁要你道歉。</p><p>隔了几分钟，她发来一句。</p><p>「我跟你说个事，你别生气」</p><p>我说，你说。</p><p>她说，他有时候说那种话。</p><p>我问，哪种。</p><p>她说，就是那种，活着没什么意思之类的话。</p><p>我看着这句话，手停在半空。</p><p>她说，他不是吓唬我，我知道他是什么人。</p><p>她说，所以我不能随便说重话。</p><p>我说，那也不能因为这个你就答应他。</p><p>她说，我没答应。</p><p>我说，那你现在这样算什么。</p><p>她说，我在拖。</p><p>我说，拖不是办法。</p><p>她说，那你告诉我什么办法是好办法。</p><p>我答不上来。</p><p>院子里有人喊小孩吃饭，声音从楼下飘上来。被子还在风里响，一下一下的。</p><p>过了一会儿，她发来一句，让我整个人都愣住了。</p><p>她说：要不你来。</p><p>我看了三遍才看明白这三个字。</p><p>我问，我来干嘛。</p><p>她说，你去跟他说。</p><p>我说，我跟他说什么。</p><p>她说，跟他说我们在一起了。</p><p>那天下午的阳光是从西边斜过来的，照在阳台的水泥地上，白花花的一片。我盯着屏幕，耳朵里嗡嗡的。</p><p>我说，这样行吗。</p><p>她说，怎么不行。</p><p>我说，那我们不就。</p><p>她说，对外说而已。</p><p>我说，对外说是假的。</p><p>她说，你非要这么说吗。</p><p>我说，我不是那个意思。</p><p>她说，那你是什么意思。</p><p>我说，我是说，这种事不能随便说。</p><p>她说，所以我问你啊。</p><p>我说，你问我什么。</p><p>她说，问你愿不愿意。</p><p>我那时候打的字是：愿意。</p><p>打完看了两秒，删了。</p><p>又打：行。</p><p>也删了。</p><p>最后我发出去的是：你想清楚了就行。</p><p>她说，意思就是你不愿意。</p><p>我说，我没说不愿意。</p><p>她说，你也没说愿意。</p><p>我说，那我说，愿意。</p><p>她说，晚了。</p><p>我说，怎么说晚就晚。</p><p>她说，你这个人就是这样，什么都要等别人问三遍。</p><p>我说，那我改。</p><p>她说，不用改，我习惯你了。</p><p>她说这句话的时候，我没有反应过来那是什么意思。我那时候满脑子都是&quot;假装的&quot;这三个字，在想这件事如果真做了，别人会怎么看，她的那个前追求者会不会信，会不会反而闹起来。</p><p>后来我想通了。她其实不是要我替她出面。她是问我会不会站出来。</p><p>这两件事差得很远，我当时没听出来。</p><p>那天晚上我们聊到很晚。中间她说她要去吃饭，走了二十分钟，回来接着聊。她把她和那个人以前的事讲了一些，讲得很碎，一会儿说一件事，一会儿又跳回前面。</p><p>她说那人以前每天都等她放学，她不走他也不走。她说有一次下大雨，那人站在校门口，伞也不打，就站着。她说她那时候心里又烦又有点过意不去。</p><p>我问，那后来呢。</p><p>她说，后来我升上来了，他还在原来的地方。</p><p>我说，你没告诉他。</p><p>她说，告诉了。他说没关系。</p><p>她说，最怕的就是这三个字。</p><p>我问，为什么。</p><p>她说，没关系的意思就是我不改，你看着办。</p><p>我一句一句接。接的中间我一直在想一件事：她跟我讲这些的时候，语气一点都不像在讲别人的事，也不像在讲自己的事。像是在念一份材料。</p><p>快十二点的时候，她忽然说，算了，不弄了。</p><p>我问，不弄什么。</p><p>她说，不让他来找你了。</p><p>我说，为什么。</p><p>她说，我自己的事，自己处理。</p><p>我说，那他要是一直发呢。</p><p>她说，发就发。</p><p>隔了一会儿，她又发来一条。</p><p>她说，你别觉得我可怜。</p><p>我说，我没有。</p><p>她说，你要是觉得我可怜，我就不跟你说了。</p><p>我说，我从来没觉得你可怜。</p><p>她说，那就好。</p><p>那天最后她发来一句话，我到现在都没听懂。</p><p>她说：你只要别哪天也这么来找我就行。</p><p>我问，什么意思。</p><p>她说，没什么意思。</p><p>她说，睡觉吧。</p><p>我说，那你别多想。</p><p>她说，嗯。</p><p>第二天早上，我醒来第一件事是去看昨晚的消息。她半夜又发过一条，是在那句&quot;睡觉吧&quot;之后很久。</p><p>只有半句话，说完就撤回了。</p><p>屏幕上留下一行小小的提示：对方撤回了一条消息。</p><p>我盯着那行字看了很久。我到今天都不知道她撤回的那半句是什么。</p><p>我后来问过一次。她说，我忘了。</p><p>她说，你也别记着了。</p>',128)])])}const m=t(o,[["render",r]]);export{u as __pageData,m as default};
